add('kinetic','mean-free-path','Molecular mean free path','Follow a molecule through successive collisions in a dilute gas.','λ = kT/(√2πd²P)','Higher pressure packs molecules closer together and reduces their mean free path.','Double pressure and watch the typical free path shorten.',[R('pressure','Gas pressure',20,200,20,100,'kPa'),R('temperature','Temperature',200,600,50,300,'K'),R('diameter','Molecular diameter',.2,.5,.05,.3,'nm',2)],p=>{let z=models.freepath(p);return[N('Mean free path',`${F(z.lambda*1e9,1)} nm`),N('Number density',`${z.density.toExponential(2)} m⁻³`),N('Mean collision rate',`${(z.speed/z.lambda/1e9).toFixed(2)} ×10⁹ s⁻¹`)]},(c,p,t)=>{let z=models.freepath(p),step=clamp(z.lambda*1e9*.6,18,85),pts=[[330,245]],a=0;rr(c,65,125,580,250,'#102d3d',C.line);for(let i=0;i<45;i++)dot(c,80+mod(i*83,550),142+mod(i*137,215),2,'#547688');for(let i=0;i<14;i++){a=i*2.399;let old=pts.at(-1),X=clamp(old[0]+step*Math.cos(a),90,610),Y=clamp(old[1]+step*Math.sin(a),150,350);pts.push([X,Y])}let n=mod(t*2,14),k=Math.floor(n);path(c,pts.slice(0,k+1),C.mint,2);for(let i=1;i<=k;i++)dot(c,...pts[i],3,C.gold);let q=n-k,xy=[pts[k][0]+q*(pts[k+1][0]-pts[k][0]),pts[k][1]+q*(pts[k+1][1]-pts[k][1])];line(c,...pts[k],...xy,C.mint,2);dot(c,...xy,7,C.gold,true);text(c,'Gold markers: successive collisions',90,99,C.gold,15);text(c,'Illustrative path; physical mean distance shown at right',80,400,C.muted,14)},p=>`λ = kT/(√2πd²P) = ${F(models.freepath(p).lambda*1e9,1)} nm`,'Dilute ideal gas with hard-sphere molecular collisions. Nitrogen molecular mass is used for the mean speed. Paths and time are schematic.',[['Lower pressure',{pressure:40}],['Higher pressure',{pressure:200}]]);
