add('pendulum','damped-oscillation','Damped harmonic motion','Add velocity-dependent resistance to a spring–mass system.','x = A₀e^(−bt/2m) cos(ωdt)','Damping removes mechanical energy and reduces the oscillation amplitude over time.','Increase damping and compare the amplitude envelope.',[R('mass','Mass',1,3,.5,1,'kg',1),R('k','Spring stiffness',10,40,5,20,'N/m'),R('damping','Damping coefficient',.2,5,.2,1.2,'kg/s',1)],(p,t)=>{let z=models.damping(p,t);return[N('Displacement',`${F(z.x,3)} m`),N('Damped frequency',`${F(z.wd/TAU)} Hz`),N('Amplitude time constant',`${F(1/z.beta,1)} s`)]},(c,p,t)=>{let z=models.damping(p,t),x=360+z.x*210;rr(c,83,122,22,96,'#42576a',C.muted);spring(c,105,x,176);rr(c,x,147,52,58,'#245766',C.mint,5);line(c,65,208,640,208,C.muted,2);line(c,360,124,360,220,C.gold,1,[4,4]);let pts=[],plus=[],minus=[];for(let i=0;i<=200;i++){let q=i/200*20,E=55*Math.exp(-z.beta*q),X=85+i*2.6;pts.push([X,320-E*Math.cos(z.wd*q)]);plus.push([X,320-E]);minus.push([X,320+E])}path(c,plus,'#8ba4b4',1);path(c,minus,'#8ba4b4',1);path(c,pts,C.mint,2);dot(c,85+z.time/20*520,320-z.x*110,5,C.gold,true);text(c,'Grey curves: exponential amplitude envelope',86,395,C.muted,14)},p=>`Amplitude time constant = 2m/b = 2×${p.mass}/${p.damping} = ${F(2*p.mass/p.damping,1)} s`,'Linear viscous damping, Fd = −bv. All available parameter combinations are underdamped. Envelope amplitude starts at 0.5 m; the displayed cosine phase implies initial velocity −(b/2m)×0.5 m/s.',[['Light damping',{damping:.2}],['Strong damping',{damping:4}]]);
add('wave','doppler','Doppler effect','Move a sound source and watch its wavefronts crowd together ahead.','fahead = f₀c/(c − vs)','A stationary observer ahead hears a higher frequency; one behind hears a lower frequency.','Raise the source speed while keeping its emitted frequency fixed.',[R('speed','Source speed',0,250,10,120,'m/s'),R('frequency','Wavefront frequency',2,6,1,4,'Hz')],p=>[N('Frequency ahead',`${F(p.frequency*340/(340-p.speed))} Hz`),N('Frequency behind',`${F(p.frequency*340/(340+p.speed))} Hz`),N('Sound speed','340 m/s')],(c,p,t)=>{let tt=mod(t,2.3),scale=.85,x=100+p.speed*tt*scale;for(let emit=0;emit<=tt;emit+=1/p.frequency){let R=340*(tt-emit)*scale,cx=100+p.speed*emit*scale;arc(c,cx,255,Math.max(1,R),0,TAU,'#42d9ca99',2)}dot(c,x,255,11,C.gold,true);arrow(c,x,255,x+35+p.speed*.12,255,C.gold,2);text(c,'WAVEFRONTS SPREAD BEHIND',60,106,C.muted,12);text(c,'CROWD AHEAD',478,106,C.mint,12);text(c,'Low frequency chosen so individual wavefronts are visible',65,397,C.muted,13)},p=>`fahead = ${p.frequency}×340/(340−${p.speed}) = ${F(p.frequency*340/(340-p.speed))} Hz`,'Subsonic source, stationary observers and still air. Source frequency is deliberately low for visible wavefronts; no sonic boom is modelled.',[['Stationary source',{speed:0}],['Moving source',{speed:240}]]);
add('electrostatic','gauss','Gauss’s law on a sphere','Resize a Gaussian sphere around a point charge and compare field with total flux.','ΦE = qenclosed/ε₀','Changing radius changes the field strength but leaves total flux unchanged.','Double the sphere radius without changing the enclosed charge.',[R('charge','Enclosed charge',-5,5,1,3,'nC'),R('radius','Gaussian radius',.5,2,.1,1,'m',1)],p=>[N('Signed electric flux',`${F(p.charge*1e-9/8.854e-12,1)} N·m²/C`),N('Field magnitude',`${F(8.988*Math.abs(p.charge)/p.radius**2)} N/C`),N('Sphere area',`${F(4*Math.PI*p.radius**2)} m²`)],(c,p,t)=>{let cx=350,cy=252,R=65+p.radius*38;arc(c,cx,cy,R,0,TAU,C.blue,2);c.save();c.setLineDash([4,5]);c.beginPath();c.ellipse(cx,cy,R,R*.3,0,0,TAU);c.strokeStyle=C.blue;c.stroke();c.restore();dot(c,cx,cy,19,p.charge<0?C.blue:C.gold,true);text(c,p.charge>0?'+':p.charge<0?'−':'0',cx,cy,'#112230',25,'center');for(let i=0;i<12&&p.charge!==0;i++){let a=i*TAU/12,start=R-16,end=R+25;if(p.charge<0)[start,end]=[end,start];arrow(c,cx+start*Math.cos(a),cy+start*Math.sin(a),cx+end*Math.cos(a),cy+end*Math.sin(a),C.mint,2)}line(c,cx,cy,cx+R,cy,C.muted,1,[4,4]);text(c,`r = ${p.radius} m`,cx+25,cy+22,C.muted,15);text(c,'Gaussian surface (spherical)',80,103,C.blue,16);text(c,'Total flux depends only on enclosed charge',80,401,C.mint,15)},p=>`Φ = ${p.charge}×10⁻⁹/(8.854×10⁻¹²) = ${F(p.charge*1e-9/8.854e-12,1)} N·m²/C`,'Point charge at the centre of a sphere in vacuum. The 2D sketch represents a 3D closed surface.',[['Small sphere',{radius:.5,charge:3}],['Large sphere',{radius:2,charge:3}]]);
