add('capacitor','capacitor-network','Capacitors in series and parallel','Connect two capacitors and compare equivalent capacitance and stored energy.','Series: 1/Ceq = 1/C₁ + 1/C₂','Series capacitors carry equal charge; parallel capacitors share the same voltage.','Compare two equal capacitors in both connections.',[R('c1','Capacitance C₁',1,10,1,4,'µF'),R('c2','Capacitance C₂',1,10,1,6,'µF'),R('voltage','Supply voltage',2,20,2,12,'V'),S('mode','Connection','series',[['series','Series'],['parallel','Parallel']])],p=>{let z=models.capnetwork(p);return[N('Equivalent capacitance',`${F(z.C)} µF`),N('Charge from supply',`${F(z.Q,1)} µC`),N('Stored energy',`${F(z.U,1)} µJ`)]},(c,p,t)=>{if(p.mode==='series'){line(c,90,254,640,254,C.mint,3);capacitor(c,260,254,`${p.c1} µF`);capacitor(c,480,254,`${p.c2} µF`);text(c,'Equal charge on both capacitors',110,361,C.gold,16)}else{for(let y of [192,307]){line(c,190,y,550,y,C.mint,3);capacitor(c,365,y,`${y===192?p.c1:p.c2} µF`)}line(c,190,192,190,307,C.mint,3);line(c,550,192,550,307,C.mint,3);line(c,70,250,190,250,C.mint,3);line(c,550,250,650,250,C.mint,3);text(c,'Same voltage across both branches',110,383,C.gold,16)}text(c,`${p.voltage} V SUPPLY`,85,108,C.white,18);for(let x of [72,645])dot(c,x,250,5,C.gold);text(c,'+',67,279,C.gold,19);text(c,'−',640,279,C.blue,19)},p=>{let z=models.capnetwork(p);return`Ceq = ${F(z.C)} µF; Q = CeqV = ${F(z.Q,1)} µC; U = ½CeqV² = ${F(z.U,1)} µJ`},'Ideal capacitors, initially uncharged, connected to a constant-voltage source. The displayed charge is total charge delivered by the supply.',[['Equal in series',{c1:4,c2:4,mode:'series'}],['Equal in parallel',{c1:4,c2:4,mode:'parallel'}]]);
