add('circuit','wheatstone','Wheatstone bridge','Adjust four resistors and bring the galvanometer reading to zero.','Balance: P/Q = R/S','At balance, the two bridge midpoints have equal potential and no current crosses the detector.','Change one resistor, then restore the balance ratio.',[R('p','Resistance P',10,100,10,20,'Ω'),R('q','Resistance Q',10,100,10,40,'Ω'),R('r','Resistance R',10,100,10,30,'Ω'),R('s','Resistance S',10,100,10,60,'Ω')],p=>{let z=models.bridge(p);return[N('Galvanometer current',`${F(z.I*1000,2)} mA`),N('Bridge state',z.balance?'Balanced':'Unbalanced'),N('P/Q and R/S',`${F(p.p/p.q)} / ${F(p.r/p.s)}`)]},(c,p,t)=>{let A=[110,250],B=[350,128],C1=[590,250],D=[350,373];for(let [a,b] of [[A,B],[B,C1],[C1,D],[D,A]])line(c,...a,...b,C.mint,3);for(let [x,y,label] of [[219,187,`P ${p.p} Ω`],[473,187,`Q ${p.q} Ω`],[219,311,`R ${p.r} Ω`],[473,311,`S ${p.s} Ω`]]){rr(c,x-39,y-16,78,32,'#574735',C.gold,4);text(c,label,x,y,C.gold,13,'center')}line(c,350,128,350,373,C.blue,2);dot(c,350,250,25,'#173b50');arc(c,350,250,25,0,TAU,C.blue,2);text(c,'G',350,250,C.white,20,'center');let z=models.bridge(p);if(!z.balance)arrow(c,365,z.I>0?207:292,365,z.I>0?232:267,C.gold,2);text(c,'6 V',70,107,C.white,17);text(c,'Detector resistance: 100 Ω',190,404,C.muted,14)},p=>{let z=models.bridge(p);return`Open midpoint voltage = 6[Q/(P+Q) − S/(R+S)] = ${F(z.open,3)} V; IG = ${F(z.I*1000,2)} mA`},'Ideal 6 V source across the left and right nodes. Galvanometer resistance is 100 Ω; current includes the bridge’s Thevenin resistance.',[['Balanced',{p:20,q:40,r:30,s:60}],['Unbalanced',{p:20,q:40,r:30,s:30}]]);
