add('magnet','magnetic-materials','How magnetic materials respond','Compare induced dipoles in diamagnetic, paramagnetic, and ferromagnetic matter.','B = μ₀(H + M)','Diamagnets oppose the applied field; paramagnets align weakly, while ferromagnets can align strongly.','Compare the three materials at the same applied field.',[S('kind','Material response','para',[['dia','Diamagnetic'],['para','Paramagnetic'],['ferro','Ferromagnetic']]),R('field','Applied field H',500,3000,250,1500,'A/m')],p=>{let z=models.material(p);return[N('Magnetisation',`${Math.abs(z.M)>1000?F(z.M/1000,1)+' kA/m':F(z.M,3)+' A/m'}`),N('Magnetic induction',`${z.B>.01?F(z.B,3)+' T':F(z.B*1000,3)+' mT'}`)]},(c,p,t)=>{rr(c,105,148,480,207,'#153c4b',C.line,8);for(let row=0;row<4;row++)for(let col=0;col<7;col++){let x=142+col*64,y=178+row*49,angle=p.kind==='dia'?Math.PI:p.kind==='para'?Math.sin(col*2.3+row*4)*.8*(1-p.field/4500):Math.sin(col+row)*.2/(1+p.field/1000);let len=p.kind==='ferro'?21:15;arrow(c,x-len*Math.cos(angle),y-len*Math.sin(angle),x+len*Math.cos(angle),y+len*Math.sin(angle),p.kind==='dia'?C.blue:C.gold,2)}arrow(c,110,105,575,105,C.mint,3);text(c,'APPLIED H →',235,83,C.mint,14);text(c,p.kind==='dia'?'Induced moments oppose H':p.kind==='para'?'Weak net alignment along H':'Strong domain alignment along H',120,397,C.muted,15)},p=>`B = μ₀(H + M); for ${p.kind==='dia'?'χ = −10⁻⁵':p.kind==='para'?'χ = 2×10⁻⁵':'M = Ms tanh(H/H₀)'}, B = ${F(models.material(p).B*1000,3)} mT`,'Illustrative material models. Diamagnetic and paramagnetic susceptibilities are fixed; ferromagnet uses Ms = 10⁶ A/m and H₀ = 800 A/m. Hysteresis and temperature effects are omitted.',[['Diamagnetic',{kind:'dia'}],['Ferromagnetic',{kind:'ferro'}]]);
