add('induction','rl-current','Current growth in an RL circuit','Close a circuit and watch an inductor oppose the rise in current.','I = (V/R)(1 − e^(−tR/L))','The inductor initially opposes the supply; its back emf falls as current approaches V/R.','Increase inductance and compare the time constant.',[R('inductance','Inductance',.1,1,.1,.5,'H',1),R('resistance','Resistance',5,40,5,10,'Ω'),R('voltage','Supply voltage',5,20,5,10,'V')],(p,t)=>{let z=models.rl(p,t);return[N('Time constant',`${F(z.tau*1000,1)} ms`),N('Current',`${F(z.I,3)} A`),N('Back-emf magnitude',`${F(z.emf,2)} V`)]},(c,p,t)=>{let z=models.rl(p,t);chart(c,{fn:x=>p.voltage/p.resistance*(1-Math.exp(-x/(z.tau*1000))),xmax:z.tau*5000,ymax:p.voltage/p.resistance,xlabel:'Time / ms',ylabel:'Current / A',marker:z.time*1000,x:95,y:355,w:510,h:180});line(c,135,113,585,113,C.mint,2);line(c,585,113,585,149,C.mint,2);line(c,585,149,135,149,C.mint,2);line(c,135,149,135,113,C.mint,2);dot(c,135,131,12,'#173b50');text(c,'+',135,129,C.gold,14,'center');resistor(c,225,113,60,'R');for(let i=0;i<5;i++)arc(c,422+i*18,113,9,Math.PI,TAU,C.gold,2);text(c,'L',457,85,C.gold,15);text(c,'DC supply • switch closes at t = 0',208,158,C.muted,12)},p=>`τ = L/R = ${p.inductance}/${p.resistance} = ${F(p.inductance/p.resistance*1000,1)} ms; I∞ = ${F(p.voltage/p.resistance,2)} A`,'Ideal DC step, fixed resistor, ideal inductor with zero winding resistance. Each animation loop covers five time constants.',[['Small inductance',{inductance:.1}],['Large inductance',{inductance:1}]]);
