add('diode','rectifier','Half-wave rectifier','Use a diode to pass the positive part of an alternating voltage.','Vout = max(0, Vin − VD)','The diode conducts only when the input exceeds its forward drop. The unfiltered output is pulsating DC.','Compare an ideal diode with a 0.7 V silicon model.',[R('amplitude','AC peak voltage',5,20,1,12,'V'),R('frequency','AC frequency',.5,2,.5,1,'Hz',1),R('drop','Diode forward drop',0,1,.1,.7,'V',1)],(p,t)=>{let z=models.rectifier(p,t);return[N('Instantaneous output',`${F(z.out,2)} V`),N('Output peak',`${F(z.peak,1)} V`),N('Diode state',z.out>0?'Conducting':'Blocking')]},(c,p,t)=>{let z=models.rectifier(p,t);line(c,120,144,565,144,C.mint,2);line(c,120,144,120,216,C.mint,2);line(c,565,144,565,216,C.mint,2);line(c,120,216,565,216,C.mint,2);diode(c,330,144);dot(c,120,179,18,'#173b50');text(c,'~',120,179,C.white,25,'center');rr(c,553,164,24,33,'#624d35',C.gold,3);text(c,'LOAD',589,180,C.gold,12);let phase=mod(t*p.frequency,2)/2,pts1=[],pts2=[];for(let i=0;i<=240;i++){let a=i/240*4*Math.PI,v=Math.sin(a)*p.amplitude;pts1.push([85+i*2.2,320-v/p.amplitude*58]);pts2.push([85+i*2.2,320-Math.max(0,v-p.drop)/p.amplitude*58])}line(c,85,320,613,320,C.line,1);path(c,pts1,C.blue,2);path(c,pts2,C.gold,3);dot(c,85+phase*528,320-Math.max(0,p.amplitude*Math.sin(phase*4*Math.PI)-p.drop)/p.amplitude*58,5,C.white,true);text(c,'Input AC',90,393,C.blue,14);text(c,'Rectified output',405,393,C.gold,14);text(c,z.out>0?'DIODE ON':'DIODE OFF',80,95,z.out>0?C.mint:C.muted,17)},p=>`Vout(t) = max[0, ${p.amplitude} sin(2π×${p.frequency}t) − ${p.drop}] V`,'Constant forward-drop diode, resistive load, no smoothing capacitor or reverse leakage. A low frequency makes the conduction intervals visible.',[['Ideal diode',{drop:0}],['Silicon approximation',{drop:.7}]]);
